#include <iostream>
#include <memory>
#include <string>
#include <unordered_map>

struct Widget {
    int id;
    Widget(int i) : id(i) { std::cout << "Creating Widget " << id << "\n"; }
    ~Widget() { std::cout << "Destroying Widget " << id << "\n"; }
};

// A factory function with a cache using weak_ptr
std::shared_ptr<const Widget> loadWidget(int id) {
    static std::unordered_map<int, std::weak_ptr<const Widget>> cache;

    // Attempt to get a shared_ptr from the weak_ptr in the cache
    if (auto sp = cache[id].lock()) { 
        std::cout << "Found Widget " << id << " in cache.\n";
        return sp; // Return existing object
    }

    std::cout << "Widget " << id << " not in cache or expired. Loading.\n";
    // Create the object, managed by a shared_ptr
    auto sp = std::make_shared<Widget>(id);
    // Store a weak_ptr in the cache
    cache[id] = sp;
    return sp;
}

int main() {
    std::shared_ptr<const Widget> w1; 
    {
        auto p1 = loadWidget(1); // Creates Widget 1
        auto p2 = loadWidget(2); // Creates Widget 2
        auto p3 = loadWidget(1); // Finds Widget 1 in cache
        w1 = p1; // Keep an external reference to Widget 1
        // p2 and p3 go out of scope, Widget 2 is destroyed
    }
    std::cout << "--- Inner scope ended ---\n";

    auto p4 = loadWidget(2); // Widget 2 was destroyed, must be re-created
    auto p5 = loadWidget(1); // Widget 1 still exists, found in cache

    return 0;
}
